    struct ACPShareRegistryStorage {
        /// @dev recipient => ids of shares addressed to them
        mapping(address => EnumerableSet.Bytes32Set) shareIdsFor;
        /// @dev share id => stored header
        mapping(bytes32 => ShareHeader) headers;
