    if (isBooleanAndNumeralFunction(funcId)) {
      for (uint8 i = 0; i < inputs.length; i++) {
        uint8 inputType = TMCommon.getUintTypeFromHash(inputs[i]);
        if ((inputType ^ Utils.EADDRESS_TFHE) == 0) {
