    uint256 ctHash,
    uint256,
    ACP memory acp
  ) public view returns (bool allowed, string memory error, uint256) {
    bool isAllowed;
    try mockAcl.isAllowedWithPermission(acp, ctHash) returns (bool _isAllowed) {
