// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

/**
 * @dev Test-only stand-in for the recipient at the heart of Consensys Diligence 5.13: a contract
 * that CANNOT accept native value (no `receive`, no payable `fallback`) but CAN make outbound
 * calls.
 *
 * That combination is the realistic shape of the finding — a vault, router or account contract
 * that simply never declared a payable entry point. An unshield naming it strands the burned value
 * forever under the original code, and its ability to call is what lets it reach the two escape
 * hatches ({claimUnshieldedAsWETH} and {reassignClaim}).
 */
contract NonPayableReceiver {
    /// @dev Forwards an arbitrary call so the test can drive the wrapper as this contract.
    function execute(address target, bytes calldata data) external returns (bytes memory) {
        (bool ok, bytes memory ret) = target.call(data);
        if (!ok) {
            assembly {
                revert(add(ret, 0x20), mload(ret))
            }
        }
        return ret;
    }
}

contracts/test/ReentrancyProbeReceiver.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

/**
 * @dev Test-only ETH recipient that re-enters the paying contract from `receive()` and RECORDS
 * what happened instead of propagating it.
 *
 * Recording rather than reverting is the point. The wrapper pays a claim with a raw
 * `call{value:}` and turns any failure into `NativeTransferFailed`, so a probe that reverted
 * would mask the inner reason and the test could not tell a reentrancy guard from a bad claim id.
 * Here the outer payout succeeds and the test inspects `lastSuccess` / `lastReturnData`, which
 * distinguishes `ReentrancyGuardReentrantCall()` (guard held) from `ClaimNotFound()` (no guard,
 * call proceeded to the claim lookup) by selector.
 */
contract ReentrancyProbeReceiver {
    address public armedTarget;
    bytes public payload;
    bool public fired;

    bool public lastSuccess;
    bytes public lastReturnData;

    /// @dev Arms the call made from inside `receive()`. Unarmed, this is an ordinary EOA-like sink.
    function arm(address target_, bytes calldata payload_) external {
        armedTarget = target_;
        payload = payload_;
        fired = false;
    }

    receive() external payable {
        if (fired || armedTarget == address(0)) return;
        fired = true;
        (bool ok, bytes memory ret) = armedTarget.call(payload);
        lastSuccess = ok;
        lastReturnData = ret;
    }
}

contracts/test/SharedAmountReceiver.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.25;

import { IERC7984Receiver } from "../interfaces/IERC7984Receiver.sol";
import { ebool, euint64, sharedEbool, sharedEuint64, FHE } from "@fhenixprotocol/cofhe-contracts/FHE.sol";

/// @notice Minimal well-behaved receiver that actually CONSUMES the shared amount, so the
///         share/receive round trip can be asserted end to end.
///
///         {MockFHERC20Receiver} decides purely on `data` and never unwraps the amount, and the two
///         malicious receivers re-enter the token as a side effect. This one just records what it
///         received, which makes it usable for two assertions the other three cannot support:
///
///           1. the legitimate path delivers the real transferred amount to the receiver; and
///           2. an arbitrary caller invoking this callback directly with a handle nobody shared
///              reverts, instead of getting an FHE operation performed on it.
contract SharedAmountReceiver is IERC7984Receiver {
    /// @notice The amount handle unwrapped from the last callback, persisted for inspection.
    euint64 public lastAmount;
    uint256 public callbackCount;

    function onConfidentialTransferReceived(
        address,
        address,
        sharedEuint64 sharedAmount,
        bytes calldata
    ) external returns (sharedEbool) {
        // Reverts unless `msg.sender` is the recorded sharer AND still holds the handle.
        euint64 amount = FHE.receiveEuint64Param(sharedAmount);

        // A received handle carries transient access only, so persisting it past this
        // transaction requires allowThis on the UNWRAPPED value.
        FHE.allowThis(amount);
        FHE.allowPublic(amount);
        lastAmount = amount;
        callbackCount += 1;

        ebool accepted = FHE.asEbool(true);
        return FHE.shareEbool(accepted, msg.sender);
    }
}

